// spec: AC #22865e77 / Figma
// seed: tests/seed.spec.ts
import { test, expect } from '@playwright/test';

test.describe('Дизайн-система — типографика, касания, цвета', () => {
  test('Line-height текстовых стилей совпадает с Figma #22865e77 @iphone @prod-safe', async ({ page }) => {
    // 1. Open /design
    await page.goto('https://banci.expo.app/design');

    // 2. For each style row read computed fontSize/lineHeight of its sample
    const styles: Array<[string, string, string]> = [
      ['Display/36-Medium', '36px', '37px'],
      ['Heading/28-Medium', '28px', '34px'],
      ['Title/20-Regular', '20px', '20px'],
      ['Title/20-Medium', '20px', '20px'],
      ['Numeric/20-Light', '20px', '20px'],
      ['Button/18-Medium', '18px', '24px'],
      ['Label/16-Medium', '16px', '20px'],
      ['Label/16-Regular', '16px', '20px'],
      ['Body/16-Regular', '16px', '22px'],
      ['Body/16-Light', '16px', '22px'],
      ['Meta/14-Regular', '14px', '18px'],
      ['Badge/12-Demibold', '12px', '16px'],
    ];

    for (const [name, fontSize, lineHeight] of styles) {
      const label = page.getByText(new RegExp(`^${name.replace('/', '\\/')} · `)).first();
      await expect(label, name).toBeVisible();
      const sample = label.locator('xpath=following-sibling::*[1]');
      const css = await sample.evaluate((el) => {
        const s = getComputedStyle(el);
        return { fontSize: s.fontSize, lineHeight: s.lineHeight };
      });
      expect(css, name).toEqual({ fontSize, lineHeight });
    }
  });
});
